async function confirmarPresenca(){
  if(!validar()) return;
  ocupado = true;
  atualizarTrava();
  try{
    const confirmadas = deps.filter(d=>d.nome.trim());
    const r = await api('confirmar', {
      telefone: soDigitos($('tel').value),
      nome: $('nome').value.trim(),
      combo: $('combo').value,
      dependentes: confirmadas,
      recado: $('recado').value.trim()
    });
    jaConfirmado = true;
    carimbar();
    avisar('Presença confirmada, ' + primeiroNome($('nome').value) + '. Dia 26.09, 12h, no Belga Pub.');
    $('dicaTel').hidden = false;
    $('tituloForm').textContent = 'Sua presença já está confirmada';
    aplicar(r);
  }catch(err){
    if(err.resposta && err.resposta.jaConfirmado) jaConfirmado = true;
    avisar('Não deu para gravar: ' + err.message, 'erro');
    aplicar(err.resposta);                       // se a casa encheu no meio do caminho, a página já mostra
  }finally{
    ocupado = false;
    atualizarTrava();
  }
});

/* -------------------------------- início -------------------------------- */
renderDeps();
carregarMural();                                 /* o contador só aparece depois de conferir com o servidor */
</script>
</body>
</html>
